int i = 5;
int j = 10;
// i is an lvalue (has persistent memory address)

int k = i + j;
// (i + j) is an rvalue (temporary result, prvalue)

// Lvalue reference MUST bind to an lvalue
int& lref = i;

// A const Lvalue reference CAN bind to an rvalue
const int& clref = i + j;

// int& bad_ref = i + j; // ERROR: cannot bind lvalue ref to rvalue
int* addr = &i; // Lvalue allows address-of operator
// int* temp_addr = &(i + j); // ERROR: Rvalue is non-addressable
---
struct Resource {};
Resource r1;

// Rvalue reference (&&) binds exclusively to rvalues/temporaries
Resource&& rref_temp = Resource{};

// int&& rref_literal = 42;

// Rvalue reference allows binding an lvalue (r1) if converted:
Resource&& rref_moved = std::move(r1); // r1 becomes an xvalue

// Function overload distinction:
void process(Resource& l) {}   // For named objects (lvalues)
void process(Resource&& r) {}  // For temporaries (rvalues)

process(r1);               // Calls Lvalue overload
process(Resource{});       // Calls Rvalue overload
process(std::move(r1));    // Calls Rvalue overload
